\label{X1.-2}\ 

    (1) The theory $T$ is a theory in the infinitary logic $\mathbb{L}_{\kappa, \aleph_{0}}$, $\chi = \kappa + \vert T \vert$ and vocabulary $\tau = \tau_{T}$, \underline{or}

    (2) $\mathfrak{k}$ is an AEC which is $\mathbf{D}$-compact (see Definition \ref{u2} and Definition \ref{y1} respectively) and $\chi = \kappa + \mathrm{LST}(\mathfrak{k}).$

\label{X1.4}
    Suppose that $<$ is a binary relation on a class $K$ of models. Let $\mu$ be a cardinal.
    $M \in K_{\le \mu}$ is a \emph{$\mu$-counter amalgamation basis} $(\mu$-c.a.b.) of
    $\mathcal K = \langle K, < \rangle$ iff
    there are $M_1, M_2 \in K_{\le \mu}$ and isomorphisms $f_i$ from $M$ into
    $M_i$ such that:

    \begin{enumerate}
        \item[(a)] $\mathrm{rng}(f_i) < M_i (i = 1,2)$,

        \item[(b)] there is no amalgam $N \in K_{\le \mu}$ of $M_1, M_2$ over $M$ with respect to $f_1, f_2$.
    \end{enumerate}

\label{u11}
    Assume $\mathfrak{k}$ is an AEC and $\tau = \tau_{\mathfrak{k}}.$ Then;

    There are $\tau_{1} = \tau_{\mathfrak{k}, 1} \supseteq \tau_{\mathfrak{k}}$ of cardinality $\vert \tau \vert + \mathrm{LST}_{\mathfrak{k}}$ and a set $\mathscr{P}$ of q.f. (quantifier free) $1$-types in $\mathbb{L}(\tau_{1})$ such that: 

    \begin{enumerate}
        \item[(A)] a $\tau$-structure $M$ belongs to $K_{\mathfrak{k}}$ \underline{iff} it can be expanded to a $\tau_{1}$-model $M^{+}$ from $K_{+}$, where: 

        \begin{itemize}
            \item $K_{+} = K_{\mathfrak{k}}^{+} = \{ N \colon N$ a $\tau_{1}$-structure omitting every  $p \in \mathscr{P}$\}. 
        \end{itemize}

        \item[(B)] If $M^{+} \in K_{+}$ and $M^{+} \, {\restriction} \, \tau \leq_{\mathfrak{k}} N$ then there is a model $N^{+} \in K_{+}$ expanding $N$ such that $M^{+} \subseteq N^{+}.$   Also, for $M, N \in K,$ we have $M \leq_{\mathfrak{k}} N$ \underline{iff} there are expansions $M^{+}, N^{+} \in K_{+}$ of $M, N$ respectively such that $M^{+} \subseteq N^{+}.$  

        \item[(C)] $(K_{+}, \subseteq)$ is an AEC with $\mathrm{LST}(K^{+}, \subseteq) = \mathrm{LST}(\mathfrak{k}).$ 

        \item[(D)] There is a set $\tau_{1}' \subseteq \tau_{1}$ of cardinality $\mathrm{LST}_{\mathfrak{k}}$ such that $A \subseteq M^{+} \in K_{+} \Rightarrow \rm{cl}_{\tau_{1}'}(A, M^{+}) \subseteq M^{+}.$

        \item[(E)] Some $\psi \in \mathbb{L}_{(2^{\lambda})^{+}, \aleph_{0}}$ defines $K_{\mathfrak{k}, 1}$ where $\lambda = \mathrm{LST}_{\mathfrak{k}} + \vert \tau_{\mathfrak{k}} \vert.$ 
    \end{enumerate}

\label{u14}\ 

    Assume $T$ is a theory in $\mathbb{L}_{\kappa, \aleph_{0}}(\tau_{T}),$ $\tau_{T}$ determined by $T$ (so $\vert T \vert \leq (\vert \tau_{T} \vert + \kappa)^{< \kappa}$) and recall $\mathcal{F}_{T}$ is the set of formulas $\varphi(\bar{x})$ such that $\varphi(\bar{x})$ is a  sub-formula of some sentence $\psi \in T.$ We define $\mathfrak{k} = \mathfrak{k}_{T}$ as follows:

   \begin{enumerate}
       \item[(A)] $K_{\mathfrak{k}}$ is the class of $\tau_{T}$-models of $T$ of cardinality $\geq \kappa + \vert T \vert$. 

       \item[(B)] $M \leq_{\mathfrak{k}} N$ \underline{iff}:

       \begin{enumerate}
           \item[(a)] $M, N \in K_{\mathfrak{k}},$

           \item[(b)] $M \subseteq N,$

           \item[(c)] $M \preceq_{\mathcal{F}} N$ i.e., if $\varphi(\bar{x}) \in \mathcal{F}_{T}$ (see below, so $\lg(\bar{x})$ is finite and $\bar{a} \in {}^{\lg(\bar{x})}M$) then $M \models \varphi[\bar{a}]$ \underline{iff} $N \models \varphi[\bar{a}].$ 
       \end{enumerate}
   \end{enumerate}

\label{u17}
    If $T$ is a theory in $\mathbb{L}_{\kappa, \aleph_{0}}(\tau_{T}),$ then: 

    \begin{enumerate}
        \item[(A)] $\mathfrak{k}_{T}$ is an AEC.

        \item[(B)] $\mathrm{LST}_{\mathfrak{k}_{T}} = \mathrm{LST}(\mathfrak{k}_{T}) \leq \vert T \vert + \kappa.$

        \item[(C)] If $T \subseteq \mathbb{L}_{\lambda^{+}, \aleph_{0}}(\tau_{T})$ then $\mathrm{LST}_{\mathfrak{k}} \leq \vert T \vert + \lambda.$ 

        \item[(D)] $\mathfrak{k}_{T}$ has no model of cardinality $< \vert \tau \vert + \kappa$ but for any $\tau(T)$-model $M$ of cardinality $\geq \vert T \vert + \kappa,$ $M \in K_{\mathfrak{k}_{T}} \Leftrightarrow M \models T.$
    \end{enumerate}

\label{u23}
    We say the AEC  \emph{$\mathfrak{k}$ is $(\mu, \lambda, \kappa)$-representable} \underline{when} there are $(\tau_{1}, T_{1}, \Gamma)$ such that: 

    \begin{enumerate}
        \item[(a)] $\tau_{1} \supseteq \tau_{\mathfrak{k}}$ has cardinality $\leq \lambda,$

        \item[(b)] $T_{1} \subseteq \mathbb{L}(\tau_{1})$ is a first order logic universal theory, so $\vert T_{1} \vert \leq \lambda,$

        \item[(c)] $\Gamma$ is a set of $\leq \mu$ $\rm{qf}$-types in $\mathbb{L}(\tau_{1}),$ each of cardinality $< \kappa,$ 

        \item[(d)] $M \in K_{\mathfrak{k}}$ \underline{iff} $M$ is the $\tau_{\mathfrak{k}}$-reduct of some $M_{2} \in \mathrm{EC}(T_{1}, \Gamma),$ where $$ \mathrm{EC}(T_{1}, \Gamma) = \{ N  \colon N \text{ a } \tau_{1} \text{-model of } T_{1} \text{ omitting every } p(x) \in \Gamma \},$$

        \item[(e)] $M \leq_{\mathfrak{k}} N$ \underline{iff} for every $M_{1} \in \mathrm{EC}(T_{1}, \Gamma)$ expanding $M$, there is $N_{1} \in \mathrm{EC}(T_{1}, \Gamma)$ expanding $N$ and extending $M_{1}.$  
    \end{enumerate}

\label{w11}\ 

    (1) We say that $(I, D, G)$ is \emph{suitable} when: 

    \begin{enumerate}
        \item[(a)] $D$ is an ultra-filter on a non-empty set $I$ (or just a filter, see Definition \ref{w5}(5)),

        \item[(b)] $G$ is a \underbar{suitable}, pedantically  a $D$-suitable filter on $I \times I$ or just a set of equivalence relations on $I$, which means:

        \begin{enumerate}
            \item[(i)]  if $e \in G$ and $e'$ is an equivalence relation on $I$ coarser than $e$, then $e' \in G,$

            \item[(ii)] $G$ is closed under finite intersections,

            \item[(iii)] $(I, D, G)$ is \emph{$\kappa$}-complete, which means that, if $e \in G$, then $D/e = \{ A \subseteq I/e: \underset{x \in A} \cup x \in D \}$ is a $\kappa$-complete ultra-filter on $I/e$ which, for simplicity, has cardinality $\kappa$.
        \end{enumerate}
    \end{enumerate}

    (2) A limit parameter $\mathbf{u}$ is \emph{suitable} when $(I_{\mathbf{u}}, E_{\mathbf{u}}, G_{\mathbf{u}})$ is. 

    (3) Suppose that $M$ is an $\tau$-structure and $(I, D, G)$ is suitable. \underline{Then} $\operatorname{Op}(M, I, D, G) = \operatorname{Op}_{I, D, G}(M)$ is the limit ultra-power $\underset{D/ \hat G} \Pi M$ where $\hat G$ is the filter on $I \times I$ generated by $G$. When clear from the context one abbreviates $\operatorname{Op}(M, I, D, G)$ by $\operatorname{Op}(M)$, pedantically $\operatorname{Op}$ stand for $\operatorname{Op}_{I, M, G}$ and one writes $f_{\operatorname{Op}} = f_{\operatorname{Op}, M}$ for the canonical map $d \colon M \to \operatorname{Op}(M);$ so we may write $f_{\operatorname{Op}}$ or $f_{\operatorname{Op}}^{M}$ instead $f_{\operatorname{Op}, M}$ when $M$ is clear from the context.

\label{w17}
    (1) Given $\kappa$-complete ultra-filters $D_1$ on $I_1, D_2$ on $I_2$  and suitable filters $G_1$ on $I_1 \times I_1, G_2$ on $I_2 \times I_2$ respectively, there exist a $\kappa$-complete ultra-filter $D$ on a set $I$ and a filter $G$ on $I \times I$ such that: $$ \operatorname{Op} (M, I, D, G) = \operatorname{Op}(\operatorname{Op}(M, I_1, D_1, G_1), I_2, D_2, G_2) $$ and $(D, G, I)$ is $\kappa$-complete. 

    (2) Also iterated ultra-power (along any linear order) with each iterand being ultra-power by $\kappa$-complete ultra-filter, gives a suitable triple (in fact, even iteration of suitable limit ultra-powers is a suitable ultra-power).

\label{X1.9.2}
    Let {\bf LO} be the class of linear orders and let $(I, \le_I) < (J, \le_J)$ mean that $(I, \le_I) \subseteq (J, \le_J)$, i.e. $(I, \le_I)$ is a suborder of $(J, \le_J)$. If $f: (I, \le_I)  \underset{\rm{nice}}{\rightarrow} (J, \le_J)$, then identifying isomorphic orders, one has $(I, \le_I) \subseteq (J, \le_J) \subseteq \operatorname{Op}(I, \le_I)$ and we 
    may write $(I, \leq_{I}) \underset{\rm{nice}}{\subseteq} (I, \leq_{J}).$

\label{X1.12}
    For every model $M$ of cardinality $\geq \kappa$ and $\lambda \geq \kappa + \mathrm{LST}_{\mathfrak{k}} + \| M\|$ there is $N$ such that
    $M \underset{\text{nice}}  {\leq} N$, $M\neq N$ and $\|N\|=\lambda$.

\label{X2.1}
    Suppose that $\chi \le \mu \le \lambda,  M, M_1, M_2 \in K_{\le \mu},  f_1 \colon M \underset{\text{nice}}  \rightarrow M_1, f_2: M \underset{\mathcal \mathfrak{k}} \rightarrow M_2$.  \underline{Then} there is an amalgam $N \in K_{\le \mu}$ of $M_1, M_2$ over $M$ with respect to $f_1, f_2$.

    Moreover, there are $N$ and $g_\ell \colon M_\ell \underset{\mathfrak{k}} \rightarrow N$ for $\ell = 1, 2$ such that $g_1f_1 = g_2 f_2$ hence $\mathrm{rng}(g_2 f_{2}) = \mathrm{rng}(g_1f_1)$ and $g_{1} \colon M_{1} \underset{\rm{nice}}{\to} N.$

y the assumption, there is $g \colon N \underset{\mathfrak{k}} \rightarrow \operatorname{Op}(M) $ such that $ g f = f_{\operatorname{Op}, M}.$ Recall  $M$ is a $\mu$- c.a.b., so for some $M_i \in K_{\le \mu}$ and $f_i \colon M \underset{\mathfrak{k}} \rightarrow M_i $ (for $i = 1,2)$ there is no amalgam of $M_1, M_2$ over $M$ w.r.t. $f_1, f_2$. Let $f^\ast_i$ be the $\leq_{\mathfrak{k}}$-elementary embedding from $\operatorname{Op}(M)$ into $\operatorname{Op}(M_i)$ induced by $f_i$ (note that $f^\ast_i f_{\operatorname{Op}, M} = f_{\operatorname{Op}, M_{i}} f_i,  i = 1,2)$. Choose $N_i$ of power $|| N ||$ such that $M_i \cup \mathrm{rng}(f^\ast_i g) \subseteq N_i \leq_{\mathfrak{k}} \operatorname{Op}(M_i)$.  Note that $f^{\ast}_{i} g \colon N \underset{\mathfrak{k}} \rightarrow N_i$. It suffices to show that there  is no amalgam of $N_1, N_2$ over $N$ w.r.t. $f^\ast_1 g, f^\ast_2 g$.

    Well, suppose that one could find an amalgam $N^\ast$ and $h_i \colon N_i \underset{\mathfrak{k}} \rightarrow N^\ast, i = 1,2$, with $h_1 (f^\ast_1 g) = h_2 (f^\ast_2 g)$.  Using Fact \ref{X1.2} choose $M^\ast, || M^\ast|| \le \mu,  M^\ast \leq_{\mathfrak{k}} N^\ast, \mathrm{rng}(h_1 f_{\operatorname{Op}} \upharpoonright M_1) \cup \mathrm{rng}(h_2 f_{\operatorname{Op}} \upharpoonright M_2) \subseteq | M^\ast|$.
    Set $g_i = h_i f_{\operatorname{Op}} \upharpoonright M_i$, for $i = 1,2$, and note that: 
    \begin{equation*}
        \begin{split}
            g_1 f_1 &= h_1 f_{\operatorname{Op}} f_1 = h_1 f^\ast_1 f_{\operatorname{Op}} = h_1 f^\ast_1 g f = h_2 f^\ast_2 g f = h_2 f^\ast_2 f_{\operatorname{Op}}\\
            & = h_2 f_{\operatorname{Op}} f_2 = g_2 f_2.
        \end{split}
    \end{equation*}

    In other words, $M^\ast$ is an amalgam of $M_1, M_2$ over $M$ w.r.t. $f_1, f_2$-contradiction.  It follows that $N$ is a $\| N \|$-c.a.b.

\label{X2.3}
    Suppose that $\mu, \lambda$ satisfy $\chi \le \mu < \lambda$.  If $M \in K_\mu$ is a $\mu$-c.a.b., then there exists $M^\ast \in K_\lambda$ such that:

    \begin{itemize}
        \item[$(\ast)$]
             $M \leq_{\mathfrak{k}} M^*$ and for every $M' \in K_{< \lambda}$, if $M \leq_{\mathfrak{k}} M' \leq_{\mathfrak{k}} M^\ast$, then $M'$ is a $|| M'||$-c.a.b.
    \end{itemize}

\label{X2.6}
    Suppose that $(I, <)$ is a suborder of the linear order $(J, <)$. We have $(I, \leq) \underset{\rm{nice}}{\subseteq} (J, <)$ when:

    \begin{enumerate}
        \item[$(\ast)$] for every $t \in J \setminus I,$
    \end{enumerate}

    \begin{enumerate}
        \item[$(\aleph)$]  $\mathrm{cf}((I, <) \restriction \{ s \in I\colon (J, <) \models s < t \}) = \kappa,$
    \end{enumerate}

    or

    \begin{enumerate}    

        \item[($\beth$)] $\mathrm{cf}((I, <)^{*} \restriction \{  s \in I\colon (J, <)^{*} \models s <^{*} t\}) = \kappa.$
    \end{enumerate}

\label{X3.1} 
    Suppose that $\mathfrak{k}$ is categorical in $\lambda$ and $\chi \le \theta < \lambda$.  If $\langle M_i \in K_\theta \colon i < \theta^+ \rangle$ is an increasing continuous $\leq_{\mathfrak{k}}$-chain, then:
    $$ \left \{ i < \theta^+  \colon M_i \underset{\text{nice}}  \leq (\cup_{j < \theta^{+}} M_{j})  \right \} \in D_{\theta^+}. $$

uppose otherwise.  We'll define a continuous increasing $\leq_{\mathfrak{k}}$-chain
    $\langle M_i \in K_\theta\colon  i < \theta^+ \rangle$ such that for $j < \theta^+$:

    \begin{enumerate}
        \item[$(*)_{j}$] $M_j \underset{\text{nice}} \nleq M_{j +1}$.
    \end{enumerate}

    For $i = 0$, put $M_0 = M$;  if $i$ is a limit ordinal, put $M_i = \underset{j < i}
    \cup M_j$;  if $i = j +1$, then since Theorem \ref{X3.3} is assumed to fail, $M_{j +1}$
    exists as required in $(\ast)_j$ (otherwise $M_j$ works as $N$ in Theorem \ref{X3.3}).  But now
    $\langle M_i \colon  i < \theta^+ \rangle$ yields a contradiction to Theorem \ref{X3.1}, since $C = \{ i < \theta^+ \colon  M_i  \underset{\mathrm{nice}}{\leq} \underset{ j < \theta^+} \cup M_j \} \in D_{\theta^+}$ by Theorem \ref{X3.1} so that choosing $j$ from $C$ one has $M_j \underset{\text{nice}} \leq M_{j +1}$ by Observation \ref{X1.10}, contradicting $(\ast)_j$.

\label{X3.7} 
    Suppose that $\mathfrak{k}$ is categorical in $\lambda, \theta \in [\chi, \lambda)$. If $M \in K_\theta$ and $M \leq_{\mathfrak{k}} N \in K_\lambda$, then there exists $M^+ \in K_\theta$ such that:

    \begin{enumerate}
        \item[(a)] $M \leq_{\mathfrak{k}} M^+ \leq_{\mathfrak{k}} N,$

        \item[(b)] $M^+$ is universal over  $M$ in $N.$
    \end{enumerate}

\label{X3.8} 
    Suppose that $\mathfrak{k}$ is categorical in
    $\lambda, \theta \in [\chi, \lambda)$, and $\langle M_i \in K_\theta \colon i < \theta^+ \rangle, \, \langle N_i \in K_\lambda \colon i < \theta^+\rangle$ are continuous $\leq_{\mathfrak{k}}$-chains such that for every $i < \theta^+$ we have $M_i \leq_{\mathfrak{k}}  N_i$.  Then there exists $i (\ast) < \theta^+$ such that $(i (\ast),\; \theta^+) \subseteq C \coloneqq \{ i < \theta^+\colon  M_{i +1}$ can be $\leq_{\mathfrak{k}}$-elementarily embedded into $N_i$ over $M_0 \}$.

\label{X3.9}
    Suppose that $\mathfrak{k}$ is categorical in $\lambda, \theta \in [\chi, \lambda),  M \in K_\theta$.  \underline{Then}
    there exists $M^+ \in K_\theta$ such that:

    \begin{enumerate}
        \item[$(\aleph)$]  $M \leq_{\mathfrak{k}} M^+$  and  $M^+$ is nice,

        \item[$(\beth)$] $M^+$ is weakly universal over $M.$
    \end{enumerate}

\label{X3.10} 
    If $\mathfrak{k}$ is categorical in $\lambda, \theta \in [\chi, \lambda)$ and $M \in K_\theta$ is an a.b. (e.g. $M$ is nice, see \ref{X2.1}), then there exists $M^+ \in K_\theta$ such that:

    \begin{enumerate}
        \item[$(\aleph)$]   $ M \leq_{\mathfrak{k}} M^+$ and $M^+$ is nice,

        \item[$(\beth)$] $M^+$ is universal over $M$.
    \end{enumerate}

y \ref{X3.3} it suffices to find a universal model of power $\theta$, noting
    that universality is preserved
    under $\leq_{\mathfrak{k}}$-elementary extensions in the same power. As in the proof of \ref{X3.7}, there is a linear order $(I, <_I)$ of power $\lambda$ and $J \subseteq I, |J| = \theta$, such that: 

    \begin{enumerate}
        \item[$(*)$] $ ( \forall J' \subseteq I)$ (if $| J'| \le \theta$, then there is an order-preserving injective map $g$ from $J'$ into $J$). 
    \end{enumerate}

    To finish the proof it suffices to prove: 

    \begin{enumerate}
        \item[$\boxplus$]  $\operatorname{EM}(J) \in K_\theta$ is universal.
    \end{enumerate}

    Why $\boxplus$ holds?  $\operatorname{EM}(J)$ is a model of power $\theta$ since max$(|J|, \chi) \le \theta$ and $\theta = |J| \le \| \operatorname{EM}(J) \|.$ Let us show that $\operatorname{EM}(J)$ is universal. Suppose that $N \in K_\theta$.  Applying Fact \ref{X1.2} to a suitably large $\operatorname{Op}(N)$ find $M \in K_\lambda, N \leq_{\mathfrak{k}} M$, so that by $\lambda$-categoricity of $\mathfrak{k}, M \cong \operatorname{EM}(I)$.  There is a surjective $\leq_{\mathfrak{k}}$-elementary embedding $h\colon  N \underset{\mathfrak{k}}  \rightarrow N' \leq_{\mathfrak{k}} \operatorname{EM}(I)$ and there exists $J' \subseteq I, \,  | J'| \le \| N' \| + \chi = \theta$, such that $N' \subseteq \operatorname{EM}(J')$.  So by $(\ast)$ there is an order preserving injective map $g$ from $J'$ into $J$. Now $g$ induces an $\leq_{\mathfrak{k}}$-elementary
    embedding $\hat g$ from $\operatorname{EM}(J')$ into $\operatorname{EM}(J)$.  Let $f = \hat g h$, then $f\colon  N \underset{\mathfrak{k}} \rightarrow \operatorname{EM}(J)$ is as required.

\label{X4.9}
    (1) If $\bar\theta_1$, $\bar\theta_2\in\Theta$, $\mathrm{rng}(\bar\theta_1)\subseteq \mathrm{rng}(\bar\theta_2)$, $\sup\mathrm{rng}(\bar\theta_1)=\sup\ \mathrm{rng}(\bar\theta_2)$, and $M$ is $\bar\theta_2$-saturated, then $M$ is $\bar\theta_1$-saturated.

    (2) For $\bar\theta\in \Theta^-$ and $\Pr(\bar \theta^\prime)$ whenever $\bar \theta^\prime\in \Theta$ is a proper initial segment of $\bar \theta$, there is a $\bar\theta$-saturated model and it is unique.

\label{X5.1}
    Suppose  that $\mu$ is singular, $\langle \mu_i \colon  i< \mathrm{cf}(\mu) \rangle$ is a continuous strictly increasing sequence of ordinals, $\mu={\underset{i< \mathrm{cf}(\mu)} \sup} \mu_i$, and $\chi \le \mu_0<\mu\le\lambda$. Then there exist a linear order $I $ of power $\mu$ and a continuous increasing sequence $\langle I_i\colon i<\mathrm{cf}(\mu)\rangle$ of linear orders such that:

    \begin{enumerate}
        \item[(a)] $\chi \le |I_i|\le\mu_i$ and $\vert I_{i} \vert < \vert I_{i + 1} \vert$ for each $i$,  

        \item[(b)] $\bigcup\limits_{i<\mathrm{cf}(\mu)}I_i=I$,

        \item[(c)] every $t\in I_{i+1}\setminus I_i$ defines a Dedekind cut of $I_i$ in
        which (at least) one side of the cut has cofinality $\kappa$.
    \end{enumerate}

\label{X5.2}
    Suppose that $\mathfrak{k}$ is categorical in $\lambda > \mathrm{cf}(\lambda), \, \kappa + \mathrm{LST}_{\mathfrak{k}} < \mu \le \lambda$. If $M \in K_\lambda$, \underline{then} there exists a continuous increasing $\prec_{\mathfrak{k}}$-chain $\langle M_i \colon  i < \mathrm{cf}(\lambda) \rangle$ of models such that:

    \begin{enumerate}
        \item[$($\rm{a})] $ M \leq_{\mathfrak{k}} \underset{i < \mathrm{cf}(\lambda)} \bigcup M_i,$

        \item[$($\rm{b})] $ \| \underset{i < \mathrm{cf}(\lambda)} \cup M_i \| = \lambda,$

        \item[$($\rm{c})] $\kappa + | T| \le \| M_i \| < \| M_{i +1} \| < \lambda,$

        \item[$($\rm{d})] for each $i < \mathrm{cf}(\lambda) , M_i \underset{\text{nice}}  \leq \left( \underset{j < \mathrm{cf}(\lambda)} \cup M_j \right)$. 
    \end{enumerate}

\label{X5.3} 
    For every $\mu \in [ \chi, \lambda]$ and $M \in K_\mu$, there exists $M' \in K_\mu, 
    M \leq_{\mathfrak{k}} M'$ such that: 

    \begin{enumerate}
        \item[$(\ast)_{M'}$]  for every $A \subseteq | M'|$, $|A|<\lambda\ \wedge\ |A|\leq \mu$, there is $N \in K_{ \chi +|A|}$ such that $A \subseteq N \leq_{\mathfrak{k}} M'$ and $N$ is nice.
    \end{enumerate}

